SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, value_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id VARCHAR(64) PRIMARY KEY,title VARCHAR(160) NOT NULL,category VARCHAR(60) NOT NULL,description TEXT NOT NULL,image VARCHAR(240) NOT NULL,price_cents INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id VARCHAR(64) NOT NULL,size VARCHAR(30) NOT NULL,color VARCHAR(60) NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY variant_unique(product_id,size,color),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipping_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(100) NOT NULL,cep_start INT UNSIGNED NOT NULL,cep_end INT UNSIGNED NOT NULL,price_cents INT UNSIGNED NOT NULL,min_days SMALLINT UNSIGNED NOT NULL,max_days SMALLINT UNSIGNED NOT NULL,active TINYINT NOT NULL DEFAULT 1,CHECK(cep_end>=cep_start),CHECK(max_days>=min_days)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS coupons (code VARCHAR(40) PRIMARY KEY,percent SMALLINT UNSIGNED NOT NULL,min_subtotal_cents INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,CHECK(percent BETWEEN 1 AND 90)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id VARCHAR(64) NOT NULL UNIQUE,access_token CHAR(64) NOT NULL UNIQUE,idempotency_hash CHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,
 state VARCHAR(30) NOT NULL DEFAULT 'creating',payer_name VARCHAR(120) NOT NULL,cpf_last4 CHAR(4) NOT NULL,customer_email VARCHAR(190) NOT NULL,shipping_json TEXT NOT NULL,
 subtotal_cents INT UNSIGNED NOT NULL,discount_cents INT UNSIGNED NOT NULL,shipping_cents INT UNSIGNED NOT NULL,total_cents INT UNSIGNED NOT NULL,coupon VARCHAR(40) NOT NULL DEFAULT '',
 shipping_label VARCHAR(100) NOT NULL,min_days SMALLINT UNSIGNED NOT NULL,max_days SMALLINT UNSIGNED NOT NULL,eta_min DATE NULL,eta_max DATE NULL,
 gateway_id VARCHAR(190) NULL UNIQUE,pix_code TEXT NULL,expires_at DATETIME NULL,paid_at DATETIME NULL,stock_released_at DATETIME NULL,inventory_attention TINYINT NOT NULL DEFAULT 0,
 fulfillment VARCHAR(30) NOT NULL DEFAULT 'pending',tracking_code VARCHAR(100) NOT NULL DEFAULT '',admin_note TEXT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX order_state(state,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,size VARCHAR(30) NOT NULL,color VARCHAR(60) NOT NULL,image VARCHAR(240) NOT NULL,quantity SMALLINT UNSIGNED NOT NULL,unit_cents INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(variant_id) REFERENCES variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,acquirer VARCHAR(50) NOT NULL,state VARCHAR(30) NOT NULL,http_status SMALLINT NULL,gateway_id VARCHAR(190) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS webhook_events (event_hash CHAR(64) PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS email_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,recipient VARCHAR(190) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'pending',attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,locked_until DATETIME NULL,sent_at DATETIME NULL,last_error VARCHAR(200) NULL,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY,hits INT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,INDEX expires(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,entity_id VARCHAR(80) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
